import java.util.*;
import java.util.function.*;

public class Main {
    static int apply(int x, IntUnaryOperator op) {
        return x;
    }

    public static void main(String[] args) {
        IntUnaryOperator twice = x -> x * 2;
        System.out.println("apply(5, double) = " + apply(5, twice));
    }
}
